'use strict';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;},fmt=n=>n.toLocaleString('th-TH'),pct=n=>(100*n).toFixed(1)+'%';
const model=globalThis.NAVIBAY_MODEL,m=model?.meta,N=globalThis.NaviBay;let current=null,selected=null,pairLimit=60,highlighted=null;
const scopeNames={inner:'ภายในวรรค',outer:'ข้ามวรรค',section:'ข้ามท่อน',end:'ท้ายวรรค',song:'ทั้งเพลง'};
const explanations={vowel:'เสียงสระ ความสั้น–ยาว และมาตราตัวสะกดตรงกัน วรรณยุกต์ต่างกันได้ เช่น ใจ–ไกล / รัก–พัก',onset:'พยัญชนะต้นเป็นเสียงเดียวกัน โดยเก็บกลุ่มควบกล้ำแยก เช่น ฟ้า–ฝัน / คิด–ขอ',coda:'มีเสียงตัวสะกดเดียวกัน แต่ส่วนสระไม่ตรงทั้งหมด เช่น รัก–มาก จึงไม่ถือเป็นสัมผัสสระตรง',assonance:'เสียงสระและความยาวตรงกัน แต่ตัวสะกดต่างกัน เช่น รัก–ฝัน ใช้สร้างเสียงซ้ำได้ แต่ไม่ใช่สัมผัสสระตรง',near:'สระและตัวสะกดอยู่ในกลุ่มเดียวกัน แต่สั้น–ยาวต่าง เช่น ใจ–กาย เป็นเพียงคู่ใกล้เคียงที่ต้องตรวจด้วยเสียงร้อง',repeat:'คำหรือพยางค์เดียวกันปรากฏซ้ำในตำแหน่งที่เปรียบเทียบ แยกจากสัมผัสสระ เพื่อไม่เพิ่มจำนวนสัมผัสตรงเพราะร้องคำเดิม',multi:'สองหรือสามพยางค์ท้ายวรรคมีชุดเสียงสัมผัสตรงกันทั้งชุด และไม่ใช่ข้อความเดียวกันทั้งหมด',phrase:'วรรคมีลำดับคำซ้ำกันทั้งวรรค เป็นเบาะแสของท่อนซ้ำหรือฮุก แต่ไม่ได้สรุปว่าเป็นฮุกโดยอัตโนมัติ'};
function reset(){current=null;selected=null;highlighted=null;$('analysis').hidden=true;$('output').hidden=true;$('empty').hidden=false;$('error').textContent='';}
function changed(){reset();$('counter').textContent=fmt($('lyrics').value.length)+' / 20,000 ตัวอักษร';}
$('lyrics').addEventListener('input',changed);
$('clear').onclick=()=>{$('lyrics').value='';$('text-file').value='';changed();$('lyrics').focus();};
$('sample').onclick=()=>{$('lyrics').value='[Verse 1]\nฝากเพลงนี้ไว้กลางใจ\nแม้คืนนี้เธออยู่ไกล\nฟ้าพราวพาเราพบฝัน\nลมแผ่วพลันบอกคิดถึงกัน\n\n[Chorus]\nเก็บความรักไว้ข้างใจ\nให้ความฝันพาเราไป\nแม้หนทางจะยาวไกล\nฉันยังรอเธอด้วยใจ\n\n[Verse 2]\nแสงดาวส่องให้เราเห็น\nลมเย็นเย็นพาใจพัก\nเมื่อใจล้าอยากหยุดพัก\nยังมีรักให้เราเห็น\n\n[Chorus]\nเก็บความรักไว้ข้างใจ\nให้ความฝันพาเราไป\nแม้หนทางจะยาวไกล\nฉันยังรอเธอด้วยใจ';changed();};
$('text-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;reset();if(file.size>100000){$('error').textContent='ไฟล์ใหญ่เกินไป รองรับข้อความไม่เกิน 20,000 ตัวอักษร';return;}const text=await file.text();if(text.length>20000){$('error').textContent='เนื้อเพลงเกิน 20,000 ตัวอักษร จึงยังไม่นำเข้า ไม่มีการตัดเนื้อเพลงอัตโนมัติ';return;}$('lyrics').value=text;changed();};
for(const [type,name] of Object.entries(N.names)){const option=el('option',name);option.value=type;$('type-filter').append(option);const item=el('details');item.append(el('summary',name),el('p',explanations[type]));$('techniques').append(item);}
const positionGuide=el('details');positionGuide.append(el('summary','สัมผัสใน–นอก / ท้ายวรรค / ข้ามท่อน'),el('p','เทียบทุกพยางค์ภายในวรรค เทียบท้ายวรรคกับพยางค์ใน 3 วรรคถัดไปของท่อนเดียวกัน และวรรคแรกของท่อนถัดไป พร้อมเชื่อมท้ายวรรคที่เสียงตรงกันตลอดทั้งเพลง จึงเห็นคู่ประชิด คู่เว้นวรรค และกลุ่มเสียงต่อเนื่องได้ ไม่ตีความว่าคู่ทั้งหมดเป็นความตั้งใจของผู้แต่ง'));$('techniques').append(positionGuide);
function edgeMatches(e){const a=current.analysis.units[e.a],b=current.analysis.units[e.b];const end=a.id===current.analysis.lineDetails[a.line].units.at(-1).id&&b.id===current.analysis.lineDetails[b.line].units.at(-1).id&&a.line!==b.line;const type=$('type-filter').value,scope=$('scope-filter').value;return (type==='all'||e.type===type)&&(scope==='all'||e.scope===scope||(scope==='end'&&end))&&(selected===null||e.a===selected||e.b===selected||e.aIds?.includes(selected)||e.bIds?.includes(selected));}
function describe(e){const a=current.analysis.units[e.a],b=current.analysis.units[e.b];const ids=e.aIds||[e.a],ids2=e.bIds||[e.b];return {a,b,left:ids.map(i=>current.analysis.units[i].text).join(''),right:ids2.map(i=>current.analysis.units[i].text).join('')};}
function renderPairs(){if(!current)return;const a=current.analysis,edges=a.edges.filter(edgeMatches);$('pair-list').replaceChildren();$('selection-title').textContent=selected===null?'คู่ที่ตรวจพบ':`“${a.units[selected].text}” คู่กับตรงไหน`;$('pair-total').textContent=`${fmt(edges.length)} คู่ · แสดง ${fmt(Math.min(pairLimit,edges.length))} คู่`;
 for(const e of edges.slice(0,pairLimit)){const d=describe(e),button=el('button',undefined,'pair-card');button.append(el('strong',`${d.left} ↔ ${d.right}`),el('span',`${N.names[e.type]} · ${scopeNames[e.scope]}`),el('small',`บรรทัด ${d.a.lineNumber} พยางค์ ${d.a.position} ↔ บรรทัด ${d.b.lineNumber} พยางค์ ${d.b.position}`));button.onclick=()=>{highlighted=e;highlight();document.getElementById('unit-'+e.a)?.scrollIntoView({block:'nearest',behavior:'smooth'});};$('pair-list').append(button);}
 if(!edges.length)$('pair-list').append(el('p','ไม่มีคู่ตามตัวกรองนี้ หรือยังอ่านเสียงพยางค์นี้ไม่ได้','muted'));$('more-pairs').hidden=pairLimit>=edges.length;highlight();}
function highlight(){if(!current)return;const matches=current.analysis.edges.filter(edgeMatches),connected=new Set();for(const e of matches)for(const id of [...(e.aIds||[e.a]),...(e.bIds||[e.b])])connected.add(id);const focus=new Set(highlighted?[...(highlighted.aIds||[highlighted.a]),...(highlighted.bIds||[highlighted.b])]:[]);for(const button of $('song-map').querySelectorAll('.unit')){const id=+button.dataset.unit;button.classList.toggle('linked',connected.has(id));button.classList.toggle('selected',id===selected||focus.has(id));button.classList.toggle('faded',selected!==null&&!connected.has(id)&&id!==selected);button.setAttribute('aria-pressed',String(id===selected));}}
function renderSong(){const a=current.analysis;$('song-map').replaceChildren();let prev=-1;for(const line of a.lineDetails){if(line.section!==prev){const heading=a.sections.find(s=>s.after===line.index)?.title||`ท่อน ${line.section+1}`;$('song-map').append(el('h3',heading,'stanza-title'));prev=line.section;}const row=el('div',undefined,'lyric-line'),num=el('span',line.number,'line-num'),content=el('div',undefined,'line-text'),badge=el('span',line.scheme,'scheme-tag');let cursor=0;for(const u of line.units){content.append(document.createTextNode(line.raw.slice(cursor,u.start)));const button=el('button',line.raw.slice(u.start,u.end),'unit'+(!u.sound?' unknown':''));button.id='unit-'+u.id;button.dataset.unit=u.id;button.title=`บรรทัด ${u.lineNumber} พยางค์ ${u.position} · คำ ${u.word}${!u.sound?' · ยังอ่านเสียงไม่ได้':''}`;button.onclick=()=>{selected=selected===u.id?null:u.id;highlighted=null;pairLimit=60;renderPairs();};content.append(button);cursor=u.end;}content.append(document.createTextNode(line.raw.slice(cursor)));row.append(num,content,badge);$('song-map').append(row);}renderPairs();}
for(const id of ['type-filter','scope-filter'])$(id).onchange=()=>{pairLimit=60;highlighted=null;renderPairs();};$('deselect').onclick=()=>{selected=null;highlighted=null;pairLimit=60;renderPairs();};$('more-pairs').onclick=()=>{pairLimit+=60;renderPairs();};
function show(){const r=current,a=r.analysis;$('empty').hidden=true;$('output').hidden=false;$('analysis').hidden=false;$('level').textContent=m.labels[r.label]+' วิว';$('range').textContent=`ใช้ครบ ${fmt(a.lines)} วรรค · ${fmt(a.tokens.length)} คำ · ${fmt(a.units.length)} หน่วยพยางค์`;$('bars').replaceChildren();r.prob.forEach((p,i)=>{const row=el('div',undefined,'bar-row'+(i===r.label?' winner':'')),label=el('div',undefined,'bar-label');label.append(el('span',m.labels[i]+' วิว'),el('strong',pct(p)));const track=el('div',undefined,'track'),fill=el('div',undefined,'fill');fill.style.width=(100*p)+'%';track.append(fill);row.append(label,track);$('bars').append(row);});$('coverage').textContent=`คำในคลังโมเดล ${fmt(r.knownWords)}/${fmt(a.tokens.length)} · อ่านเสียงพยางค์ได้ ${pct(a.recognized/Math.max(1,a.units.length))}${a.recognized/a.units.length<.6?' · ความครอบคลุมเสียงต่ำ ควรตรวจการแบ่งพยางค์':''}`;
 $('stats').textContent=`วิเคราะห์ข้อความที่กรอกทั้งหมด ${fmt(a.lines)} วรรค ใน ${a.structures.length} ท่อน ไม่มีการเฉลี่ยผลทำนายรายวรรค`; $('summary').replaceChildren();for(const [type,n] of Object.entries(a.counts)){const item=el('button',undefined,'summary-item');item.append(el('span',N.names[type]),el('strong',fmt(n)));item.onclick=()=>{$('type-filter').value=type;selected=null;pairLimit=60;renderPairs();};$('summary').append(item);} $('schemes').replaceChildren();for(const s of a.structures){const item=el('div',undefined,'scheme-row');item.append(el('span',`ท่อน ${s.section+1} · บรรทัด ${s.from}–${s.to}`),el('code',s.scheme));$('schemes').append(item);}renderSong();}
function lookup(){const q=$('rhyme-search').value.trim();$('lookup').replaceChildren();if(!q||!m)return;const found=model.rhymePairs?model.rhymePairs.filter(([f])=>f.split(':').at(-1).split('|').includes(q)).slice(0,30).map(([f,n])=>({f,n})):model.vocab.filter(f=>f.startsWith('r:')&&f.split(':').at(-1).split('|').includes(q)).map(f=>({f,n:model.counts.reduce((s,c)=>s+(c[f]||0),0)})).sort((a,b)=>b.n-a.n).slice(0,30);for(const {f,n} of found){const [,type,scope,pair]=f.split(':');$('lookup').append(el('span',`${pair.replace('|','–')} · ${N.names[type]} (${scopeNames[scope]}) · ${fmt(n)} ครั้ง`,'chip'));}if(!found.length)$('lookup').textContent='ไม่พบคู่พยางค์นี้ในชุดฝึก';}$('rhyme-search').oninput=lookup;
if(!m||(model.version!==2&&model.version!==3)){$('error').textContent='โหลดโมเดลรุ่นใหม่ไม่สำเร็จ กรุณารีเฟรชหน้าเว็บ';}else{
 $('predict').disabled=false;$('predict').textContent='วิเคราะห์และทายช่วงยอดวิวทั้งเพลง';lookup();
 for(const [label,value] of [['Accuracy 7 ช่วง',pct(m.accuracy)],['ทายช่วงส่วนใหญ่',pct(m.baseline)],['Macro-F1',m.macroF1.toFixed(3)]]){const metric=el('div',label,'metric');metric.append(el('strong',value));$('metrics').append(metric);}
 $('comparison').textContent=`ชุดทดสอบเดียวกัน: คำและโครงสร้าง (CNB) ${pct(m.unigramAccuracy)} / โมเดลเต็ม (Hybrid) ${pct(m.accuracy)} · คำตอบอยู่ใน 2 อันดับแรก ${pct(m.topTwo)} · คลาดเคลื่อนไม่เกิน 1 ช่วง ${pct(m.withinOne)} (สองค่านี้ไม่ใช่ความแม่นยำแบบตรงช่วง)`;
 if(m.accuracy<m.baseline){const warning=el('p',`โมเดล 7 ช่วงยังแม่นยำน้อยกว่าการทายช่วงส่วนใหญ่ (${pct(m.accuracy)} เทียบ ${pct(m.baseline)}) ใช้เป็นต้นแบบทดลอง ไม่ใช่ประมาณการยอดวิวที่เชื่อถือได้`,'model-warning');$('bars').after(warning);}
 $('data-details').textContent=`ข้อมูล ${fmt(m.sourceRows)} แถว เหลือ ${fmt(m.usable)} เพลงหลังกรองและลบซ้ำ ฝึก ${fmt(m.train)} / ทดสอบ ${fmt(m.test)} เพลง`;
 for(const c of m.perClass){const row=el('tr');[c.label,fmt(c.train),fmt(c.test),pct(c.precision),pct(c.recall),c.f1.toFixed(3)].forEach(v=>row.append(el('td',v)));$('class-table').append(row);}
 $('predict').onclick=async()=>{const text=$('lyrics').value;reset();if(text.length>20000){$('error').textContent='รองรับไม่เกิน 20,000 ตัวอักษร ไม่มีการตัดข้อความอัตโนมัติ';return;}if(text.split(/\r?\n/).some(line=>N.words(line).length>120)){$('error').textContent='มีวรรคยาวเกิน 120 คำ กรุณาขึ้นบรรทัดตามวรรคที่ร้องเพื่อวิเคราะห์ตำแหน่งสัมผัส';return;}if(N.words(text).length<10){$('error').textContent='กรุณากรอกเนื้อเพลงอย่างน้อย 10 คำ และใส่ทุกท่อนที่ต้องการวิเคราะห์';return;}$('predict').disabled=true;$('predict').textContent='กำลังอ่านทุกวรรค…';await new Promise(resolve=>setTimeout(resolve,30));try{current=N.predict(model,text);if(!current.knownWords){current=null;throw Error('ไม่พบคำที่โมเดลรู้จัก กรุณาใช้เนื้อเพลงภาษาไทย');}selected=null;pairLimit=60;show();}catch(error){$('error').textContent=error.message;}finally{$('predict').disabled=false;$('predict').textContent='วิเคราะห์และทายช่วงยอดวิวทั้งเพลง';}};
}
$('export').onclick=()=>{if(!current)return;const blob=new Blob([JSON.stringify({modelVersion:model.version,viewBands:m.labels,probabilities:current.prob,predictedBand:m.labels[current.label],analysis:current.analysis},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='navibay-whole-song.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
